  // ------------------------------------------------------------------ //
  // Deep check. The counting report above can only DISPROVE a timetable.
  // This asks CP-SAT whether one actually exists.
  // Two response shapes: {mode:'sync', status:…} or {mode:'queued', task_id:…}
  // ------------------------------------------------------------------ //
  const DEEP_URL = "/pro/pro_dashboard/api/auto-gen-preflight/deep/";
  const PROGRESS_URL = "/pro/pro_dashboard/api/task-progress/TASKID/";
  const deepBtn = document.getElementById('pf-deep-check');
  const deepOut = document.getElementById('pf-deep-result');

  function renderDeep(status, seconds) {
    if (status === 'feasible') {
      deepOut.innerHTML = '<div class="alert alert-success py-2 mb-0">'
        + '<i class="fas fa-check-circle"></i> '
        + "تأكّد: يمكن بناء جدول كامل. لن تُحذف أي حصة."
        + (seconds ? ' <span class="text-muted small">(' + seconds + 's)</span>' : '')
        + '</div>';
      if (genBtn) genBtn.disabled = false;
    } else if (status === 'infeasible') {
      deepOut.innerHTML = '<div class="alert alert-danger py-2 mb-0">'
        + '<i class="fas fa-ban"></i> '
        + "لا يوجد جدول مثالي بهذه الإعدادات. عدّ الساعات لم يكن كافياً لاكتشاف ذلك: القطع لا يمكن ترتيبها. إذا وَلَّدت الآن، سيتخلى النظام عن القواعد في المدرسة كلها وستبقى خلايا كثيرة فارغة."
        + '</div>';
      if (genBtn) genBtn.disabled = true;
      if (ackBox) ackBox.style.display = '';
    } else {
      deepOut.innerHTML = '<div class="alert alert-secondary py-2 mb-0">'
        + '<i class="fas fa-hourglass-half"></i> '
        + "انتهى وقت الفحص العميق دون إجابة قاطعة. قد يترك التوليد بعض الخلايا فارغة."
        + '</div>';
    }
    deepBtn.disabled = false;
    deepBtn.innerHTML = '<i class="fas fa-redo"></i> ' + "إعادة تشغيل الفحص العميق";
  }

  function pollProbe(taskId) {
    const url = PROGRESS_URL.replace('TASKID', taskId);
    const started = Date.now();
    const timer = setInterval(function () {
      if (Date.now() - started > 120000) {   // 2 min ceiling
        clearInterval(timer);
        renderDeep('inconclusive');
        return;
      }
      fetch(url).then(r => r.json()).then(function (p) {
        if (p.state === 'SUCCESS') {
          clearInterval(timer);
          renderDeep((p.result && p.result.status) || 'inconclusive',
                     p.result && p.result.solve_seconds);
        } else if (p.state === 'FAILURE') {
          clearInterval(timer);
          renderDeep('inconclusive');
        } else if (p.message) {
          deepOut.innerHTML = '<div class="text-muted small py-1">'
            + '<i class="fas fa-spinner fa-spin"></i> ' + p.message + '</div>';
        }
      }).catch(function () { clearInterval(timer); renderDeep('inconclusive'); });
    }, 1500);
  }

  if (deepBtn) {
    deepBtn.addEventListener('click', function () {
      deepBtn.disabled = true;
      deepBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> '
        + "جارٍ الفحص… قد يستغرق بضع ثوانٍ";
      deepOut.innerHTML = '';

      fetch(DEEP_URL, {
        method: 'POST',                     // never GET: this burns CPU
[authentication reference omitted]
      })
      .then(r => r.json())
      .then(function (data) {
        if (data.mode === 'sync') {
          renderDeep(data.status, data.solve_seconds);
        } else if (data.mode === 'queued') {
          deepOut.innerHTML = '<div class="text-muted small py-1">'
            + '<i class="fas fa-spinner fa-spin"></i> '
            + "النظام مشغول — فحصك في قائمة الانتظار…" + '</div>';
          pollProbe(data.task_id);
        } else {
          renderDeep('inconclusive');
        }
      })
      .catch(function () { renderDeep('inconclusive'); });
    });
  }

  if (genBtn) genBtn.addEventListener('click', function () {
    let settings;
    try { settings = JSON.parse(sessionStorage.getItem(PF_SETTINGS_KEY)); }
    catch (e) { settings = null; }

    // Came here by direct link — we have no options to replay.
    if (!settings) { window.location.href = SETUP_URL; return; }

    settings.acknowledged_preflight = true;

    genBtn.disabled = true;
    genBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> جارٍ البدء…';

    scrollToTop();

    fetch(GEN_URL, {
      method: 'POST',
      headers: {
        'content-Type': 'application/json',
[authentication reference omitted]
      },
      body: JSON.stringify(settings),
    })
      .then(r => r.json())
      .then(data => {
        if (data.success === true) {
          sessionStorage.removeItem(PF_SETTINGS_KEY);
          const type = String(settings['distribute-type']);
          if (BALANCE_TYPES.includes(type) && data.task_id) {
            window.startGlobalProgressPolling(data.task_id, data.time_limit || 600);
          } else {
            setTimeout(() => { window.location.href = PREVIEW_URL; }, 3000);
          }
        } else {
          const msg = data.message ||
            (data.messages || []).join(' ') ||
            "تعذّر بدء التوليد. يرجى المحاولة مرة أخرى.";
          alert(msg);
          genBtn.disabled = false;
          genBtn.innerHTML = '<i class="fas fa-bolt"></i> التوليد على أي حال';
        }
      })
      .catch(() => {
        genBtn.disabled = false;
        genBtn.innerHTML = '<i class="fas fa-bolt"></i> التوليد على أي حال';
      });
  });
